package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1000000007

type factor struct {
	p int64
	e int
}

func expectedPrimePower(p int64, exponent, k int) int64 {
	dp := make([]int64, exponent+1)
	next := make([]int64, exponent+1)
	inv := make([]int64, exponent+2)

	inv[1] = 1
	for i := 2; i <= exponent+1; i++ {
		inv[i] = (mod - (mod/int64(i))*inv[mod%int64(i)]%mod) % mod
	}

	dp[exponent] = 1

	for step := 0; step < k; step++ {
		var sum int64
		for e := exponent; e >= 0; e-- {
			sum = (sum + dp[e]*inv[e+1]) % mod
			next[e] = sum
		}
		dp, next = next, dp
	}

	var result int64
	power := int64(1)
	p %= mod
	for e := 0; e <= exponent; e++ {
		result = (result + dp[e]*power) % mod
		power = power * p % mod
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n int64
	var k int
	fmt.Fscan(in, &n, &k)

	x := n
	factors := make([]factor, 0)

	for _, p := range []int64{2, 3} {
		if x%p == 0 {
			e := 0
			for x%p == 0 {
				x /= p
				e++
			}
			factors = append(factors, factor{p, e})
		}
	}

	for p, step := int64(5), int64(2); p*p <= x; p, step = p+step, 6-step {
		if x%p == 0 {
			e := 0
			for x%p == 0 {
				x /= p
				e++
			}
			factors = append(factors, factor{p, e})
		}
	}

	if x > 1 {
		factors = append(factors, factor{x, 1})
	}

	answer := int64(1)
	for _, f := range factors {
		answer = answer * expectedPrimePower(f.p, f.e, k) % mod
	}

	fmt.Fprintln(out, answer)
}

