import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1000000007

type Factor struct {
	p int64
	a int
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int64
	var k int
	fmt.Fscan(in, &n, &k)

	x := n
	factors := make([]Factor, 0)

	addFactor := func(p int64) {
		a := 0
		for x%p == 0 {
			x /= p
			a++
		}
		factors = append(factors, Factor{p, a})
	}

	if x%2 == 0 {
		addFactor(2)
	}
	if x%3 == 0 {
		addFactor(3)
	}

	for d, step := int64(5), int64(2); d <= x/d; d, step = d+step, 6-step {
		if x%d == 0 {
			addFactor(d)
		}
	}
	if x > 1 {
		factors = append(factors, Factor{x, 1})
	}

	maxExp := 0
	for _, f := range factors {
		if f.a > maxExp {
			maxExp = f.a
		}
	}

	inv := make([]int64, maxExp+2)
	if maxExp+1 >= 1 {
		inv[1] = 1
	}
	for i := 2; i <= maxExp+1; i++ {
		inv[i] = mod - (mod/int64(i))*inv[mod%int64(i)]%mod
	}

	answer := int64(1)

	for _, f := range factors {
		a := f.a
		dp := make([]int64, a+1)
		next := make([]int64, a+1)
		dp[a] = 1

		for step := 0; step < k; step++ {
			suffix := int64(0)
			for j := a; j >= 0; j-- {
				suffix += dp[j] * inv[j+1] % mod
				if suffix >= mod {
					suffix -= mod
				}
				next[j] = suffix
			}
			dp, next = next, dp
		}

		expected := int64(0)
		power := int64(1)
		p := f.p % mod

		for e := 0; e <= a; e++ {
			expected = (expected + dp[e]*power) % mod
			power = power * p % mod
		}

		answer = answer * expected % mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 1000000007

type factor struct {
	p int64
	e int
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int64
	var k int
	fmt.Fscan(in, &n, &k)

	x := n
	factors := make([]factor, 0)

	if x%2 == 0 {
		e := 0
		for x%2 == 0 {
			x /= 2
			e++
		}
		factors = append(factors, factor{2, e})
	}

	for d := int64(3); d <= x/d; d += 2 {
		if x%d == 0 {
			e := 0
			for x%d == 0 {
				x /= d
				e++
			}
			factors = append(factors, factor{d, e})
		}
	}
	if x > 1 {
		factors = append(factors, factor{x, 1})
	}

	var inv [64]int64
	inv[1] = 1
	for i := int64(2); i < int64(len(inv)); i++ {
		inv[i] = MOD - (MOD/i)*inv[MOD%i]%MOD
	}

	answer := int64(1)

	for _, f := range factors {
		cur := make([]int64, f.e+1)
		next := make([]int64, f.e+1)

		cur[0] = 1
		p := f.p % MOD
		for i := 1; i <= f.e; i++ {
			cur[i] = cur[i-1] * p % MOD
		}

		for step := 0; step < k; step++ {
			var prefix int64
			for i := 0; i <= f.e; i++ {
				prefix += cur[i]
				if prefix >= MOD {
					prefix -= MOD
				}
				next[i] = prefix * inv[i+1] % MOD
			}
			cur, next = next, cur
		}

		answer = answer * cur[f.e] % MOD
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}
